# 20_fig5_fit.R: Figure 5, environmental spread and position (original MS-GDUM structure: I-spline spread terms + position + geographic distance) for EPA macroinvertebrates and zooplankton,
# incidence ("total", Sorensen-type, 1 - shared / mean richness) and relative-abundance dissimilarity. Predictors: log10 TP, TN, Chl-a and geographic distance.
# (a) leave-one-spatial-block-out (5 complete-linkage blocks): held-out D2 of spread-only (NNLS), spread + linear position and spread + nonlinear position; within-order Shapley/Owen importance of spread and position per predictor (held-out block), 3 seeds;
# (b) all-lake fit: conditional response curves (predicted and observed dissimilarity along TP/TN/Chl-a/distance spread and position; equal-count bins) on independent sets. Usage: POOL=shared|full Rscript 20_fig5_fit.R
source("common.R"); source("lib_ugdm.R"); library(parallel); NC <- as.integer(Sys.getenv("NCORES", "9")); POOL <- Sys.getenv("POOL", "shared"); SEEDS <- 1:3; M_TR <- 3000L; M_EV <- 3000L
O <- read.csv("tables/evaluated_orders.csv"); ords <- function(cc) as.integer(O[O$community == COMM[[cc]] & O$pool == POOL & O$informative, "order"]); RESP <- c(incidence = "total", relative = "relative")
jobs <- list(); for (cc in c("BM", "ZP")) for (k in ords(cc)) for (s in SEEDS) jobs[[length(jobs) + 1]] <- list(cc = cc, k = k, seed = s)
DATA <- lapply(c("BM", "ZP"), function(cc) { d <- POOLS[[POOL]][[cc]]; xy <- as.matrix(d$env[, c("lon", "lat")]); list(x = d$x, e = get_env(d$env), xy = xy, DM = hav(xy), fold = spatial_folds(xy)) }); names(DATA) <- c("BM", "ZP")
cv1 <- function(j) { D <- DATA[[j$cc]]; k <- j$k; V <- list(); IM <- list()
  for (f in sort(unique(D$fold))) { tr <- which(D$fold != f); te <- which(D$fold == f); if (length(te) < k + 2) next
    il <- sample_sets(length(tr), k, M_TR, seed = 10 * j$seed + f); el <- sample_sets(length(te), k, M_EV, seed = 100 * j$seed + f)
    for (rn in names(RESP)) { r <- ugdm_response(D$x[tr, , drop = FALSE], il, RESP[[rn]]); rt <- ugdm_response(D$x[te, , drop = FALSE], el, RESP[[rn]]); if (sum(r$keep) < 50 || sum(rt$keep) < 50) next
      # spread-only comparator: NNLS fit of the spread (and distance) terms on the original design (internal routine used in the earlier hold-out analysis)
      d0 <- ugdm_design(D$e[tr, ], il, dist_matrix = D$DM[tr, tr]); d1 <- ugdm_design(D$e[te, ], el, dist_matrix = D$DM[te, te], ref = d0)
      so <- tryCatch({ xa <- cbind(d0$Xdir, d0$Xdist); xb <- cbind(d1$Xdir, d1$Xdist); fit <- zetaGDUM:::.fit_logit_nnls(-xa[r$keep, , drop = FALSE], r$y[r$keep], r$trials[r$keep]); p <- plogis(fit$intercept - drop(xb %*% fit$coef)); heldout_D2(r, rt, p) }, error = function(e) NA_real_)
      V[[length(V) + 1]] <- data.frame(community = COMM[[j$cc]], pool = POOL, order = k, seed = j$seed, fold = f, response = rn, model = "spread_only", D2_heldout = so, D2_train = NA_real_, converged = NA)
      for (m in MODELS$model) { res <- tryCatch({ dsg <- build(D$e[tr, ], il, D$DM[tr, tr], m); fit <- fit1(dsg, r); dte <- build(D$e[te, ], el, D$DM[te, te], m, ref = dsg); p <- ugdm_predict(fit, dte$int)
            V[[length(V) + 1]] <- data.frame(community = COMM[[j$cc]], pool = POOL, order = k, seed = j$seed, fold = f, response = rn, model = m, D2_heldout = heldout_D2(r, rt, p), D2_train = fit$D2, converged = isTRUE(fit$converged))
            if (m == "linear_const") { im <- ugdm_within_order_importance(fit, dsg$int, r$y[r$keep], r$trials[r$keep], evaluation = dte$int, evaluation_y = rt$y[rt$keep], evaluation_trials = rt$trials[rt$keep], seed = j$seed, failure = "warn"); h <- im$hierarchy; h$community <- COMM[[j$cc]]; h$pool <- POOL; h$order <- k; h$seed <- j$seed; h$fold <- f; h$response <- rn; h$D2_heldout <- heldout_D2(r, rt, p); IM[[length(IM) + 1]] <- h }
          }, error = function(e) { message("ERR ", conditionMessage(e)); NULL }) } } }
  list(v = bind_rows(V), im = bind_rows(IM)) }
t0 <- Sys.time(); R <- mclapply(jobs, cv1, mc.cores = NC, mc.preschedule = FALSE); cat("validation/importance elapsed", format(Sys.time() - t0), "jobs", length(jobs), "\n")
V <- bind_rows(lapply(R, `[[`, "v")); IM <- bind_rows(lapply(R, `[[`, "im")); write.csv(V, sprintf("tables/fig5_validation_folds_%s.csv", POOL), row.names = FALSE); write.csv(IM, sprintf("tables/fig5_importance_folds_%s.csv", POOL), row.names = FALSE)
# ---- (b) all-lake fits and conditional response curves
setstats <- function(il, v) { k <- ncol(il); pos <- rowMeans(matrix(v[il], nrow(il))); sp <- rep(0, nrow(il)); for (a in 1:(k - 1)) for (b in (a + 1):k) sp <- sp + abs(v[il[, a]] - v[il[, b]]); list(pos = pos, spread = sp / choose(k, 2)) }
curves <- mclapply(jobs[sapply(jobs, function(j) j$seed == 1)], function(j) { D <- DATA[[j$cc]]; k <- j$k; n <- nrow(D$x); il <- sample_sets(n, k, 6000, seed = 7000 + k); el <- sample_sets(n, k, 8000, seed = 9000 + k); out <- list()
  dist_set <- function(il) { s <- rep(0, nrow(il)); for (a in 1:(k - 1)) for (b in (a + 1):k) s <- s + D$DM[cbind(il[, a], il[, b])]; s / choose(k, 2) }
  for (rn in names(RESP)) { r <- ugdm_response(D$x, il, RESP[[rn]]); rt <- ugdm_response(D$x, el, RESP[[rn]]); dsg <- build(D$e, il, D$DM, "linear_const"); fit <- fit1(dsg, r); dte <- build(D$e, el, D$DM, "linear_const", ref = dsg); p <- ugdm_predict(fit, dte$int); kk <- rt$keep
    out[[length(out) + 1]] <- data.frame(community = COMM[[j$cc]], pool = POOL, order = k, response = rn, quantity = "fit", predictor = NA, axis = NA, bin = NA, x = NA, n_sets = NA, predicted = NA, observed = NA, D2_train = fit$D2, converged = isTRUE(fit$converged), D2_all_sets_heldout_sites_not_independent = heldout_D2(r, rt, p))
    for (v in c(names(D$e), "distance")) for (ax in c("spread", "position")) { xs <- if (v == "distance") { if (ax == "spread") dist_set(el) else NULL } else setstats(el, D$e[[v]])[[if (ax == "spread") "spread" else "pos"]]; if (is.null(xs)) next
      b <- cut(xs[kk], quantile(xs[kk], seq(0, 1, .1)), include.lowest = TRUE, labels = FALSE); out[[length(out) + 1]] <- data.frame(community = COMM[[j$cc]], pool = POOL, order = k, response = rn, quantity = "curve", predictor = v, axis = ax, bin = 1:10, x = tapply(xs[kk], b, mean), n_sets = as.integer(table(b)), predicted = tapply(p[kk], b, mean), observed = tapply(rt$y[kk], b, mean), D2_train = fit$D2, converged = isTRUE(fit$converged), D2_all_sets_heldout_sites_not_independent = NA) } }
  bind_rows(out) }, mc.cores = NC, mc.preschedule = FALSE); write.csv(bind_rows(curves), sprintf("tables/fig5_response_curves_%s.csv", POOL), row.names = FALSE); cat("done\n")
